    en: {
    eyebrow: "Platform governance", title: "Security center", description: "Review real authentication, authorization, role, session, and audit records.", refresh: "Refresh data", overview: "Overview", roles: "Roles & access", audit: "Audit history", events: "Security events", sessions: "Admin sessions", policy: "Security policy", loading: "Loading security records…", error: "Security data unavailable", retry: "Retry", dataSource: "Data source", database: "Database-backed security records", activeAdmins: "Active admin assignments", activeSessions: "Active admin sessions", failedLogins: "Failed logins (24h)", deniedRequests: "Denied requests (24h)", roleChanges: "Role changes (24h)", unresolvedAlerts: "Unresolved alerts", noEvents: "No events recorded", notConfigured: "Not configured", recentActions: "Recent privileged actions", noActions: "No privileged actions recorded yet.", role: "Role", permissions: "Permissions", assignments: "User assignments", search: "Search users", save: "Save role", revoke: "Revoke", readOnly: "Read-only access. A platform super administrator is required for changes.", noUsers: "No user assignments found.", auditEmpty: "No audit records found.", eventsEmpty: "No security events recorded.", timestamp: "Timestamp", actor: "Actor", action: "Action", outcome: "Outcome", event: "Event", target: "Target", sessionOwner: "Account", created: "Created", expires: "Expires", revokeSession: "Revoke session", noSessions: "No administrator sessions found.", policyTitle: "Persisted platform security policy", mfa: "Require administrator MFA", sessionTimeout: "Session timeout (minutes)", maxAttempts: "Maximum login attempts", retention: "Audit retention (days)", accessReview: "Access review frequency (days)", savePolicy: "Save policy", policySaved: "Security policy saved.", mfaUnavailable: "MFA cannot be required until a supported provider is configured.", alertTitle: "Alerts", alertNotConfigured: "No platform alert rules are configured.", active: "Active", revoked: "Revoked", verified: "Verified", unverified: "Unverified", yes: "Yes", no: "No",
  },
